import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer, ErrorMessage } from 'components';
import { useCurrentPage, usePageFilterApplied, usePageFilterData } from 'hooks';

import { formatScopedGeoTitle } from '../../../../utils/formatScopedGeoTitle';
import type { InnovationHubPortfolioSectionData } from '../../types';
import { PortfolioBigNumbers } from '../PortfolioBigNumbers';
import { PortfolioPieChart } from '../PortfolioPieChart';
import {
  StyledInnovationPortfolioRoot,
  StyledPieChartsRow,
  StyledPieChartsState,
} from './InnovationPortfolio.styles';

/** Max portfolio donut cards (loading placeholders only; order comes from BFF). */
const PORTFOLIO_PIE_CHART_SKELETON_COUNT = 3;

export interface InnovationPortfolioProps {
  dataTestId?: string;
  portfolioData: InnovationHubPortfolioSectionData;
}

export const InnovationPortfolio: React.FC<InnovationPortfolioProps> = ({
  dataTestId,
  portfolioData: { bigNumbers, pieCharts, loading, error },
}) => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);

  const sectionTitle = useMemo(
    () =>
      formatScopedGeoTitle(formatMessage, {
        applied,
        dataFilters,
        globalTitleId: 'Innovation.InnovationHub.Overview.Portfolio.title',
        scopedTitleId:
          'Innovation.InnovationHub.Overview.Portfolio.sectionTitle',
      }),
    [applied, dataFilters, formatMessage],
  );

  const showPieSkeletons = loading && !error && pieCharts.length === 0;

  let pieChartsContent: React.ReactNode = pieCharts.map((chart) => (
    <PortfolioPieChart
      key={chart.id}
      chartId={chart.id}
      title={chart.title}
      period={chart.period}
      slices={chart.slices}
      loading={loading}
      dataTestId={`portfolio-pie-chart-${chart.id}`}
    />
  ));

  if (error) {
    pieChartsContent = (
      <StyledPieChartsState>
        <ErrorMessage dataTestId="innovation-portfolio-pie-charts-error" />
      </StyledPieChartsState>
    );
  } else if (showPieSkeletons) {
    pieChartsContent = Array.from(
      { length: PORTFOLIO_PIE_CHART_SKELETON_COUNT },
      (_, index) => (
        <PortfolioPieChart
          key={`pie-skeleton-${index}`}
          chartId="liquidType"
          title=""
          slices={[]}
          loading
          dataTestId={`portfolio-pie-chart-skeleton-${index}`}
        />
      ),
    );
  }

  return (
    <StyledInnovationPortfolioRoot data-testid={dataTestId}>
      <BasicContainer
        dataTestId="innovation-portfolio"
        layout={{
          background: '#fafafa',
          border: 'gray',
          bodyPadding: false,
        }}
        header={{
          title: sectionTitle,
          titleSize: 'H1',
        }}
      >
        <PortfolioBigNumbers
          data={bigNumbers}
          loading={loading}
          error={error}
        />
        <StyledPieChartsRow>{pieChartsContent}</StyledPieChartsRow>
      </BasicContainer>
    </StyledInnovationPortfolioRoot>
  );
};
